(* [comment removed for export] *)
Definition dbp_segB_post (sp gp tp a0 a1 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rav s0v s1v s2v s3v s4v s5v s6v : word) (OPT ec lo : Z) (j0 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0' a1' a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0' a1' a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (OPT, OPT + 24); (ec, ec + 24)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' OPT [C1 (b8 1); CB 7 (skipn 1 j0); C8 a0; C8 a1]
    /\ rw_cells bsegs m' ec (ErrCodeCells EC_clear)
    /\ ACONST m'.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma dbp_segB : asan_memset_stmt -> asan_memcpy_stmt ->
  forall (OPT ec ev lo shi : Z) (pcv rax rav s0v s1v s2v s3v s4v s5v s6v e0 e1 e2 : word) (fj j0 j1 j2 : list byte)
    sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (pcv = Z_to_bv 64 P_A_DBP_RET \/ pcv = ret_pc (Z_to_bv 64 P_A_DBP_RET)) ->
  rw_cells bsegs m (bv_unsigned sp + -96) (dbp_frame fj s6v s5v s4v s3v s2v s1v s0v rav) ->
  rw_cells bsegs m OPT [CB 8 j0; CB 8 j1; CB 8 j2] -> OPT mod 8 = 0 -> aapp OPT 24 -> accessible m OPT 24 -> shvis m OPT (OPT + 24) -> (OPT + 24 <= lo \/ bv_unsigned sp <= OPT) ->
  rw_cells bsegs m ec [C8 e0; C8 e1; C8 e2] -> aapp ec 24 -> accessible m ec 24 -> shvis m ec (ec + 24) -> ec + 24 <= aceil ->
  (OPT + 24 <= ec \/ ec + 24 <= OPT) ->
  stk bsegs m lo (bv_unsigned sp + -96) -> lo + 128 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
